<?php
require_role('admin');
$periods=ak_rows('SELECT t.*,p.mulai,p.selesai,p.catatan FROM tahun_ajaran t JOIN ak_periode p USING(id_tahun_ajaran) WHERE p.terverifikasi=1 AND t.dikunci=0 ORDER BY p.mulai DESC');$sources=[];
foreach($periods as $p)if($p['semester']==='Genap')$sources[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' · Genap · '.$p['catatan'];
$fromId=($_GET['periode_asal']??'')!==''?input_id($_GET,'periode_asal'):(int)($_SESSION['ak_kenaikan']['periode_asal']??0);
$from=$fromId?ak_one('SELECT t.*,p.mulai,p.selesai FROM tahun_ajaran t JOIN ak_periode p USING(id_tahun_ajaran) WHERE t.id_tahun_ajaran=?',[$fromId]):null;
$targetYear=$from&&preg_match('/^(\d{4})\/(\d{4})$/D',$from['tahun_ajaran'],$yearParts)?((int)$yearParts[1]+1).'/'.((int)$yearParts[2]+1):null;
$targetOptions=[];foreach($periods as $p)if($p['semester']==='Ganjil'&&$targetYear!==null&&$p['tahun_ajaran']===$targetYear&&$p['mulai']>$from['selesai'])$targetOptions[$p['id_tahun_ajaran']]=$p['tahun_ajaran'].' · Ganjil';
$classes=$from?ak_rows('SELECT k.*,COUNT(*) jumlah FROM ak_anggota_kelas a JOIN kelas k ON k.id_kelas=a.id_kelas WHERE a.id_tahun_ajaran=? AND a.mulai<=? AND a.selesai>=? GROUP BY k.id_kelas ORDER BY k.nama_kelas',[$fromId,$from['selesai'],$from['selesai']]):[];
$available=ak_rows("SELECT * FROM kelas WHERE status='aktif' ORDER BY nama_kelas");
$preview=$_SESSION['ak_kenaikan']??null;if($preview&&($preview['expires']<time()||$preview['actor']!==ak_actor()||($fromId&&(int)$preview['periode_asal']!==$fromId))){unset($_SESSION['ak_kenaikan']);$preview=null;}
?><section class="panel"><h2>Kenaikan kelas seluruh siswa</h2><p>X → XI, XI → XII, XII → alumni. Pilih semester Genap asal dan Ganjil tahun berikutnya. Sistem memakai anggota kelas pada akhir semester asal; nilai, rapor, absensi dan keanggotaan lama dipertahankan.</p><p>Pratinjau wajib sebelum penerapan. Kelas tujuan yang sudah berisi siswa atau histori tidak ditimpa. Periode terkunci tidak dapat diproses. Perpindahan efektif pada tanggal mulai periode tujuan; tahun aktif tidak diganti otomatis.</p><div class="actions"><a class="button secondary" href="/admin/master.php?table=siswa">Tambah siswa baru</a><a class="button secondary" href="/admin/master.php?table=kelas">Kelola kelas</a><a class="button secondary" href="/admin/tahun_ajaran.php">Tahun & semester</a><a class="button secondary" href="<?=e(ak_link('fondasi'))?>">Keanggotaan & batas periode</a><a class="button secondary" href="<?=e(ak_link('alumni'))?>">Lihat alumni</a></div><p class="muted">Siswa baru kelas X ditambahkan pada Master Siswa, lalu diberi keanggotaan bertanggal di Akademik.</p></section>
<?php if(!$sources):?><div class="notice">Belum ada periode Genap yang terverifikasi dan tidak dikunci. Buat / tinjau tahun & semester serta batas periode di Akademik. Data kelas X sekarang tetap pada periode asalnya.</div><?php endif;?>
<form method="get" class="panel form-grid"><?php ak_hidden('view','kenaikan');?><label class="field"><span>Semester Genap asal</span><select name="periode_asal" required><option value="">Pilih periode yang akan diproses</option><?php foreach($sources as $id=>$label):?><option value="<?=e($id)?>" <?=(int)$id===$fromId?'selected':''?>><?=e($label)?></option><?php endforeach;?></select></label><button class="secondary">Muat kelas asal</button></form>
<?php if($classes):?><section class="panel"><h2>Pemetaan kelas</h2><form method="post"><?=csrf_field()?><?php ak_hidden('action','kenaikan_preview');ak_hidden('periode_asal',$fromId);ak_select('periode_tujuan','Semester Ganjil tujuan',$targetOptions);?>
<div class="card-grid"><?php foreach($classes as $class):$next=$class['tingkat']==='X'?'XI':'XII';$opts=[];$suggest='';
if($class['tingkat']==='XII')$opts=['alumni'=>'Alumni'];else foreach($available as $candidate)if($candidate['tingkat']===$next&&(int)$candidate['id_jurusan']===(int)$class['id_jurusan']){$opts[$candidate['id_kelas']]=$candidate['nama_kelas'];if($candidate['nama_kelas']===preg_replace('/^X[I]* /',$next.' ',$class['nama_kelas']))$suggest=$candidate['id_kelas'];}
?><div class="history-entry"><h3><?=e($class['nama_kelas'])?> · <?=e($class['jumlah'])?> siswa</h3><?php ak_select('tujuan['.$class['id_kelas'].']','Tujuan',$opts,$class['tingkat']==='XII'?'alumni':$suggest);?></div><?php endforeach;?></div>
<?php ak_field('alasan','Dasar keputusan kenaikan / kelulusan');?><button type="submit">Pratinjau Naik Kelas</button></form></section><?php endif;?>
<?php if($preview):?><section class="panel"><h2>Pratinjau · <?=e($preview['jumlah'])?> siswa</h2><p>Belum ada perubahan tersimpan. Berlaku dari awal periode tujuan. Token berlaku 15 menit dan hanya sekali pakai.</p><div class="table-scroll"><table><thead><tr><th>Asal</th><th>Tujuan</th><th>Siswa</th></tr></thead><tbody><?php foreach($preview['classes']as $c):?><tr><td><?=e($c['asal'])?></td><td><?=e($c['tujuan'])?></td><td><?=e($c['jumlah'])?></td></tr><?php endforeach;?></tbody></table></div>
<form method="post"><?=csrf_field()?><?php ak_hidden('action','kenaikan_commit');ak_hidden('preview_token',$preview['token']);?><label class="check"><input type="checkbox" name="konfirmasi" value="1" required><span>Saya menyetujui pemetaan dan keputusan kenaikan / kelulusan seluruh <?=e($preview['jumlah'])?> siswa ini.</span></label><button type="submit">Terapkan Naik Kelas</button></form>
</section><?php endif;?>
<?php
$batchId=($_GET['batch']??'')!==''?input_id($_GET,'batch'):null;
if($batchId):$batch=ak_one('SELECT b.*,u.username FROM ak_kenaikan_batch b JOIN users u ON u.id_user=b.created_by WHERE b.id=?',[$batchId]);if(!$batch)not_found();
$total=(int)ak_query('SELECT COUNT(*) FROM ak_kenaikan_detail WHERE id_batch=?',[$batchId])->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);
?><section class="panel"><h2>Hasil batch #<?=e($batchId)?></h2><p><?=e($batch['jumlah'])?> siswa · berlaku <?=e($batch['tanggal_berlaku'])?> · <?=e($batch['username'])?></p><p><?=e($batch['alasan'])?></p><div class="table-scroll"><table><thead><tr><th>NIS</th><th>Nama</th><th>Asal</th><th>Tujuan</th><th>Hasil</th></tr></thead><tbody><?php foreach(ak_rows("SELECT d.*,s.nama_siswa,k.nama_kelas,kt.nama_kelas tujuan FROM ak_kenaikan_detail d JOIN siswa s ON s.nis=d.nis JOIN ak_anggota_kelas a ON a.id=d.id_anggota_asal JOIN kelas k ON k.id_kelas=a.id_kelas LEFT JOIN ak_anggota_kelas t ON t.id=d.id_anggota_tujuan LEFT JOIN kelas kt ON kt.id_kelas=t.id_kelas WHERE d.id_batch=? ORDER BY d.id LIMIT ".crud_page_limit()." OFFSET $offset",[$batchId])as $r):?><tr><td><?=e($r['nis'])?></td><td><?=e($r['nama_siswa'])?></td><td><?=e($r['nama_kelas'])?></td><td><?=e($r['tujuan']??'Alumni')?></td><td><?=e($r['hasil'])?></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></section>
<?php else:$total=(int)ak_query('SELECT COUNT(*) FROM ak_kenaikan_batch')->fetchColumn();[$page,$pages,$offset]=crud_page_bounds($total);?><section class="panel"><h2>Riwayat kenaikan kelas</h2><div class="table-scroll"><table><thead><tr><th>Batch</th><th>Asal</th><th>Tujuan</th><th>Berlaku</th><th>Jumlah</th><th>Admin</th></tr></thead><tbody><?php foreach(ak_rows("SELECT b.*,a.tahun_ajaran asal,t.tahun_ajaran tujuan,u.username FROM ak_kenaikan_batch b JOIN tahun_ajaran a ON a.id_tahun_ajaran=b.periode_asal JOIN tahun_ajaran t ON t.id_tahun_ajaran=b.periode_tujuan JOIN users u ON u.id_user=b.created_by ORDER BY b.id DESC LIMIT ".crud_page_limit()." OFFSET $offset")as $b):?><tr><td><a href="<?=e(ak_link('kenaikan',['batch'=>$b['id']]))?>">#<?=e($b['id'])?></a></td><td><?=e($b['asal'])?></td><td><?=e($b['tujuan'])?></td><td><?=e($b['tanggal_berlaku'])?></td><td><?=e($b['jumlah'])?></td><td><?=e($b['username'])?></td></tr><?php endforeach;?></tbody></table></div><?php crud_pager($page,$pages,$total);?></section><?php endif;?>
